with base as (select *, case when browser in ('Safari', 'Firefox') then 'Core' else 'Other' end browser_group, coalesce(country, 'NONE') country_clean from sessions where customer_id is not null and started_at > to_timestamp('2023-05-06 19:00:00')), with_windows as (select id, customer_id, device, browser_group, row_number() over w_running row_seq, last_value(country) ignore nulls over (partition by date_trunc('YEAR', started_at) order by started_at, id rows between unbounded preceding and current row) last_known_country, row_number() over (partition by date_trunc('month', started_at), browser order by started_at desc, id) row_seq_2, row_number() over (partition by to_date(started_at) order by started_at, id) seq_no from base where hour(started_at) between 10 and 14 window w_running as (partition by country order by started_at, id)), enriched as (select s.*, d.city, d.credit_limit, d.segment from with_windows s inner join customers d on s.customer_id = d.id), joined as (select e.id, e.customer_id, e.device, e.row_seq_2, e.segment, c.segment as customer_segment, c.signup_date from enriched e left join customers c on e.customer_id <=> c.id), with_dims as (select e.*, c.age from joined e inner join customers c on e.customer_id <=> c.id) select case when row_seq_2 >= 8 then 'LARGE' else 'SMALL' end as row_seq_2_tier, device, count(*) as row_count, percentile_approx(row_seq_2, 0.95) as row_seq_2_p95 from with_dims group by 1, 2
